import {proofPrepayment,proofPaymentSettled} from './proof-payment-policy.mjs';
const el=(tag,text)=>{const node=document.createElement(tag);if(text)node.textContent=text;return node;};
export function eproofApiPanel(order,{api,refresh,say,checkout}){
 const manual=!order.proof?.api;if(manual&&(!order.checkoutId||!proofPrepayment(checkout)||order.decision?.decision!=='approve'))return null;
 if(!order.decision||!['approval_pending_pf','revision_requested'].includes(order.status))return null;
 const section=el('section');section.className='order-primary-task';const approved=order.decision.decision==='approve',dispatch=order.decision.apiDispatch;
 section.append(el('h2',approved?(manual?'Godkend korrektur og betaling':'Godkend betaling og send til PF'):'Send ændringsønske til PF'));
 for(const c of order.proof.api?.configurations||[])section.append(el('p',`${c.reference} · ${c.description}`));
 if(dispatch){section.append(el('p',dispatch.state==='delivered'?'Beslutningen er sendt via PF API. PF’s endelige bekræftelse af godkendelsen registreres særskilt.':'Afsendelsen afventer afstemning med PF. Der sendes ikke igen, da PF kan have modtaget svaret.'));return section;}
 if(approved&&proofPrepayment(checkout))section.append(el('p','Når alle korrekturer på ordren er godkendt af kunden og Smerch, hæves hele beløbet én gang. PF-godkendelsen afsendes først efter bekræftet betaling. Ved fejl eller uafklaret betaling stoppes afsendelsen.'));
 const artwork=[];
 if(!approved){section.append(el('p',order.decision.comment));const files=el('div'),add=el('button','Tilføj nyt artwork');add.type='button';add.onclick=()=>{const row=el('div'),fields={};for(const [name,label] of [['artUrl','Offentligt HTTPS-link til trykfil'],['color','Farve / Full Color'],['height','Højde i mm'],['width','Bredde i mm']]){const wrapper=el('label',label),input=el('input');input.setAttribute('aria-label',label);if(name==='artUrl')input.type='url';fields[name]=input;wrapper.append(input);row.append(wrapper);}const remove=el('button','Fjern artwork');remove.type='button';const entry={row,fields};artwork.push(entry);remove.onclick=()=>{artwork.splice(artwork.indexOf(entry),1);row.remove();};row.append(remove);files.append(row);};section.append(files,add);if(order.decision.attachments?.length)section.append(el('p','Kundens bilag skal gennemgås og klargøres som offentlige artwork-links til PF.'));
 }
 const checkbox=el('input');checkbox.type='checkbox';const label=el('label',approved&&proofPrepayment(checkout)?'Jeg har gennemgået korrekturen og kundens godkendelse. Jeg godkender hævningen og derefter frigivelsen til PF.':'Jeg har gennemgået korrekturen og kundens svar og godkender, at dette svar sendes til PF.');label.prepend(checkbox);
 const send=el('button',approved?(proofPrepayment(checkout)&&!proofPaymentSettled(checkout)?(manual?'Godkend og hæv betaling':'Godkend, hæv og send til PF'):(manual?'Bekræft intern godkendelse':'Godkend og send til PF')):'Godkend ændringsønske og send til PF');send.className='primary';send.disabled=true;checkbox.onchange=()=>{send.disabled=!checkbox.checked;};
 send.onclick=async()=>{send.disabled=true;try{const response=await api(`/api/pf-orders/${order.id}/${manual?'proof-payment':'eproof-send'}`,'POST',{version:order.proof.version,confirmed:checkbox.checked,newArt:artwork.map(({fields})=>Object.fromEntries(Object.entries(fields).map(([key,input])=>[key,input.value.trim()])))});const result=typeof response.json==='function'?await response.json():response;await refresh();say(result.state==='awaiting_other_proofs'?'Din godkendelse er gemt. Afventer kunde- og medarbejdergodkendelse af de øvrige korrekturer. Ingen betaling eller PF-afsendelse endnu.':manual?'Betalingen er bekræftet. Du kan nu sende godkendelsen via den manuelle PF-kanal.':approved?'Betalingskontrollen er gennemført, og godkendelsen er sendt til PF.':'Ændringsønsket er sendt til PF. Ingen betaling er hævet.');}catch(error){await refresh();say(error.message);}};
 section.append(label,send,el('p','Kundens svar afsendes først, når en medarbejder godkender her.'));return section;
}
